import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import HomePage from './pages/HomePage.jsx';
import StudentSection from './pages/StudentSection.jsx';
import StudentSearchPage from './pages/StudentSearchPage.jsx';
import FacultySection from './pages/FacultySection.jsx';
import FacultySearchPage from './pages/FacultySearchPage.jsx';
import AboutPage from './pages/AboutPage.jsx';
import ContactPage from './pages/ContactPage.jsx';
import FeeSection from './pages/FeeSection.jsx';
import CoursesPage from './pages/CoursesPage.jsx';
import AdminLogin from './pages/AdminLogin.jsx';
import { AuthProvider, useAuth } from './context/AuthContext';
import './App.css';

const ProtectedRoute = ({ children }) => {
  const { isAdmin } = useAuth();
  if (!isAdmin) {
    return <Navigate to="/admin/login" />;
  }
  return children;
};

function App() {
  return (
    <AuthProvider>
      <Router>
        <Routes>
          <Route path="/" element={<Navigate to="/admin/login" />} />
          <Route path="/admin/login" element={<AdminLogin />} />
          <Route path="/home" element={<ProtectedRoute><HomePage /></ProtectedRoute>} />
          <Route path="/students" element={<ProtectedRoute><StudentSection /></ProtectedRoute>} />
          <Route path="/student-search" element={<ProtectedRoute><StudentSearchPage /></ProtectedRoute>} />
          <Route path="/faculty" element={<ProtectedRoute><FacultySection /></ProtectedRoute>} />
          <Route path="/faculty-search" element={<ProtectedRoute><FacultySearchPage /></ProtectedRoute>} />
          <Route path="/about" element={<AboutPage />} />
          <Route path="/contact" element={<ContactPage />} />
          <Route path="/fees" element={<ProtectedRoute><FeeSection /></ProtectedRoute>} />
          <Route path="/courses" element={<ProtectedRoute><CoursesPage /></ProtectedRoute>} />
        </Routes>
      </Router>
    </AuthProvider>
  );
}

export default App;
